  margin: 0;
  padding: 0;
}

:root {
  --bg-page:        #0d0f12;
  --bg-surface:     #161a1f;
  --bg-surface-2:   #1e2329;
  --bg-dialog:      #1a1e24;
  --border:         #2c3240;
  --text-primary:   #e8eaf0;
  --text-secondary: #8b93a8;
  --text-muted:     #4f5770;
  --accent-red:     #e05252;
  --accent-red-hover: #c43c3c;
  --accent-red-active: #a82e2e;
  --btn-ghost-hover: rgba(255, 255, 255, 0.06);
  --btn-ghost-border: #3a4157;
  --focus-ring:     #6089e8;
  --shadow-dialog:  0 24px 64px rgba(0, 0, 0, 0.7), 0 4px 16px rgba(0, 0, 0, 0.5);
}

html {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text-primary);
  background-color: var(--bg-page);
  -webkit-font-smoothing: antialiased;
}

body {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--focus-ring);
  color: #fff;
  border-radius: 0 0 6px 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 0;
}

/* ── Header ── */
.site-header {
  display: flex;
  align-items: center;
  padding: 0 2rem;
  height: 56px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  gap: 0.75rem;
  flex-shrink: 0;
}

.site-header svg {
  color: var(--text-secondary);
}

.site-header h1 {
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--text-primary);
}

/* ── Main ── */
main {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3rem 1rem;
  gap: 2.5rem;
}

/* ── Image card ── */
.image-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.image-preview {
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--bg-surface-2);
  overflow: hidden;
}

/* Placeholder image with gradient */
.image-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-badge {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.25rem 0.6rem;
  border-radius: 20px;
  letter-spacing: 0.03em;
}

.image-meta {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

.image-meta h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
}

.image-meta p {
  font-size: 0.825rem;
  color: var(--text-secondary);
}

.image-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  gap: 0.75rem;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s, border-color 0.15s, color 0.15s, box-shadow 0.15s;
  white-space: nowrap;
  line-height: 1.4;
}

.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn-ghost {
  background: transparent;
  border-color: var(--btn-ghost-border);
  color: var(--text-secondary);
}
.btn-ghost:hover {
  background: var(--btn-ghost-hover);
  color: var(--text-primary);
}

.btn-danger {
  background: transparent;
  border-color: #5e2a2a;
  color: var(--accent-red);
}
.btn-danger:hover {
  background: rgba(224, 82, 82, 0.1);
  border-color: var(--accent-red);
}
.btn-danger:active {
  background: rgba(224, 82, 82, 0.18);
}

.btn-danger-solid {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #fff;
}
.btn-danger-solid:hover {
  background: var(--accent-red-hover);
  border-color: var(--accent-red-hover);
}
.btn-danger-solid:active {
  background: var(--accent-red-active);
  border-color: var(--accent-red-active);
}

.btn-cancel {
  background: var(--bg-surface-2);
  border-color: var(--border);
  color: var(--text-primary);
}
.btn-cancel:hover {
  background: #272d38;
  border-color: #3d4560;
}

/* ── Dialog ── */
dialog {
  background: transparent;
  border: none;
  padding: 0;
  max-width: 100%;
  width: 100%;
}

dialog::backdrop {
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(3px);
}

.dialog-box {
  background: var(--bg-dialog);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: var(--shadow-dialog);
  width: 100%;
  max-width: 420px;
  margin: 0 auto;
  overflow: hidden;
  animation: dialog-in 0.18s ease-out;
}

@keyframes dialog-in {
  from { opacity: 0; transform: scale(0.96) translateY(-8px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

.dialog-header {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.5rem 1.5rem 1rem;
}

.dialog-icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(224, 82, 82, 0.15);
  border: 1px solid rgba(224, 82, 82, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-red);
}

.dialog-title-group {
  flex: 1;
  padding-top: 0.1rem;
}

.dialog-title-group h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.25rem;
  line-height: 1.3;
}

.dialog-title-group p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.dialog-image-preview {
  margin: 0 1.5rem 1.25rem;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--border);
  aspect-ratio: 16 / 6;
  background: var(--bg-surface-2);
}

.dialog-image-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  opacity: 0.7;
}

.dialog-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.75rem;
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--border);
  background: rgba(0, 0, 0, 0.15);
}

