const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const b = await chromium.launch();
  const page = await b.newPage();

  // Test 1: default (dialog closed)
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Test 2: dialog open
  await page.evaluate(() => document.getElementById('delete-dialog').showModal());
  const r2 = await page.evaluate(async () => await window.axe.run());

  await b.close();

  const fmt = (v) => ({ id: v.id, impact: v.impact, tags: v.tags, targets: v.nodes.map(n => n.target) });
  const all = [...r1.violations, ...r2.violations];
  const seen = new Set();
  const deduped = all.filter(v => { if (seen.has(v.id)) return false; seen.add(v.id); return true; });

  const wcag = deduped.filter(v => !v.tags.includes('best-practice'));
  const bp   = deduped.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({ wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
EOF", 'description': 'Run axe accessibility audit', 'initial_wait': 30}, intention_summary='Run axe accessibility audit', mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.FUNCTION: 'function'>)

